---Cutscene layers are layer-like components used for 2D cutscene playback.
---
---Warning: Cutscenes aren't currently exposed to the plugin API, however existing cutscene layers can be accessed as
---regular layers.
---@class ui.CutsceneLayer : ui.Layer

---Identifies why a cutscene finished playing on a cutscene layer component.
---@enum ui.CutscenePlaybackEndReason
ui.CutscenePlaybackEndReason = {
    ---The cutscene finished playing normally.
    FINISHED = 0,
    ---Playback was manually cancelled by the user.
    CANCELLED = 1,
    ---The cutscene was interrupted by another cutscene.
    INTERRUPTED = 2,
    ---The cutscene's playback was interrupt due to the interface in which its layer resided being closed.
    INTERFACE_CLOSED = 3,
}
